foreach ($r in $roots) {
  if (Test-Path $r) {
    Get-ChildItem -Directory $r | Where-Object { Test-Path (Join-Path $_.FullName ".git") } | ForEach-Object { $repos += $_.FullName }
  }
}
$repos = $repos | Select-Object -Unique
"repos: $($repos.Count)"
foreach ($p in $repos) {
  $dirty = (git -C $p status --porcelain 2>$null | Measure-Object).Count
